import{_ as e,o as r,c as a,a3 as o}from"./chunks/framework.DhF4LrUq.js";const g=JSON.parse('{"title":"Glossary","description":"The ShipperDog glossary - every term of the platform in one line, from organization to telemetry token, with links to the pages that go deeper.","frontmatter":{"description":"The ShipperDog glossary - every term of the platform in one line, from organization to telemetry token, with links to the pages that go deeper."},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),n={name:"reference/glossary.md"};function s(i,t,d,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>The platform&#39;s vocabulary, one line per term. Each entry links to the page that explains it properly — start at <a href="/shipperdog/snapshot/get-started/concepts">core concepts</a> for the five nouns that carry everything else.</p><h2 id="the-object-model" tabindex="-1">The object model <a class="header-anchor" href="#the-object-model" aria-label="Permalink to &quot;The object model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In one line</th></tr></thead><tbody><tr><td><strong>Organization</strong></td><td>The top-level enterprise account: members, roles, rings, approval workflows, gate definitions, and policies all live here.</td></tr><tr><td><strong>Tenant</strong></td><td>A customer or business entity inside the organization, owning its testers, groups, and (usually) its applications; data is isolated per tenant by construction.</td></tr><tr><td><strong>Application</strong></td><td>A mobile app under management, registered with its bundle id (iOS) and/or package name (Android), owned by a tenant or organization-shared.</td></tr><tr><td><strong>Version</strong></td><td>A logical release-train of one application (7.12.0); carries one artifact per platform and freezes the moment any release references it.</td></tr><tr><td><strong>Artifact</strong></td><td>The concrete immutable binary a tester installs — uploaded with provenance, validated through a seven-stage pipeline, identified by SHA-256.</td></tr><tr><td><strong>Release</strong></td><td>The distribution event: one version&#39;s artifacts taken to a chosen audience through rings, approvals, and gates.</td></tr><tr><td><strong>Tester</strong></td><td>The person on the phone — linked to tenants, organized in groups, granted access to versions; uses only the <a href="/shipperdog/snapshot/roles/tester">Tester Portal</a>.</td></tr><tr><td><strong>Tester group</strong></td><td>A named audience inside one tenant (Internal QA, Pilot, UAT) that narrows who a release targets.</td></tr><tr><td><strong>Environment</strong></td><td>An organization-level deployment context (with versioned configuration) that a release can name — for example a staging or production context.</td></tr></tbody></table><p>Deep dives: <a href="/shipperdog/snapshot/concepts/tenancy-isolation">the tenancy model</a> · <a href="/shipperdog/snapshot/concepts/artifact-pipeline">the artifact pipeline</a> · <a href="/shipperdog/snapshot/concepts/release-lifecycle">the release lifecycle</a></p><h2 id="access-and-identity" tabindex="-1">Access and identity <a class="header-anchor" href="#access-and-identity" aria-label="Permalink to &quot;Access and identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In one line</th></tr></thead><tbody><tr><td><strong>Membership</strong></td><td>The link that makes a tester part of a tenant — without an active one, the tenant&#39;s apps and groups do not exist for them.</td></tr><tr><td><strong>Grant</strong></td><td>Permission for a tester to see an application&#39;s builds: explicit per version, by application, by tag, or &quot;latest N&quot;.</td></tr><tr><td><strong>Authorization</strong></td><td>The seven-layer decision chain that every API call and download runs; only an ALLOW mints a download.</td></tr><tr><td><strong>Concealed denial</strong></td><td>The rule that a denied caller gets the byte-identical 404 a genuine miss produces — existence is information, so refusals never hint.</td></tr><tr><td><strong>Personal access token (PAT)</strong></td><td>The token that authenticates CLI and CI calls to the API; minted in the Console, shown exactly once.</td></tr><tr><td><strong>SSO</strong></td><td>Signing in through your company&#39;s identity provider (OIDC or SAML) instead of email and password.</td></tr><tr><td><strong>SCIM</strong></td><td>The provisioning protocol that pushes joiners, movers, and leavers from the identity provider into ShipperDog automatically.</td></tr><tr><td><strong>ABAC policy</strong></td><td>An attribute-based access rule (DENY or REQUIRE) evaluated inside the authorization chain, usually for tenant or release scoping.</td></tr></tbody></table><p>Deep dives: <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> · <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO</a> · <a href="/shipperdog/snapshot/concepts/security-model">the security model</a></p><h2 id="release-governance" tabindex="-1">Release governance <a class="header-anchor" href="#release-governance" aria-label="Permalink to &quot;Release governance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In one line</th></tr></thead><tbody><tr><td><strong>Ring</strong></td><td>A rung of the promotion ladder (engineering, internal, beta, production...); a release sits on exactly one ring and climbs one hop at a time.</td></tr><tr><td><strong>Promotion</strong></td><td>The act of widening a release to the next ring — evaluated against gates, approvals, eligibility, and policies before it commits.</td></tr><tr><td><strong>Precheck</strong></td><td>The read-only command that runs the exact evaluation a promotion would run, returning the verdict and every blocker without writing anything.</td></tr><tr><td><strong>Approval workflow</strong></td><td>The named chain of roles (with ALL/ANY/conditional semantics) that a release must satisfy on its way through a ring.</td></tr><tr><td><strong>Approval round</strong></td><td>One pass of the workflow&#39;s decisions on one release — satisfied, rejected, or restarted after rework.</td></tr><tr><td><strong>Gate</strong></td><td>A measurable release requirement (tests passed, coverage threshold, crash-free rate) whose failed or missing state blocks, fail-closed.</td></tr><tr><td><strong>Evidence URL</strong></td><td>The mandatory http(s) link a gate result carries — the report a human can follow; a gate without proof does not exist.</td></tr><tr><td><strong>Override</strong></td><td>The governed exception that stops a failed or data-less gate from blocking — exactly once, with a mandatory, audited reason.</td></tr><tr><td><strong>Policy hold</strong></td><td>A named release-policy rule that pauses a crossing until an authorized person acknowledges it — a recorded human decision, not a silent pass.</td></tr><tr><td><strong>Manifest</strong></td><td>The frozen, immutable record of an approved release — what shipped, where it came from, and to whom it was targeted.</td></tr><tr><td><strong>Provenance</strong></td><td>The build facts captured at upload — commit, branch, pipeline, CI run URL, timestamp — so every artifact says where it was born.</td></tr><tr><td><strong>Rollback</strong></td><td>The ROLLED_BACK crossing that cuts a release&#39;s downloads at the moment of the crossing; the record is never erased.</td></tr></tbody></table><p>Deep dives: <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a> · <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> · <a href="/shipperdog/snapshot/how-to/console/rollback">rollback how-to</a></p><h2 id="distribution" tabindex="-1">Distribution <a class="header-anchor" href="#distribution" aria-label="Permalink to &quot;Distribution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In one line</th></tr></thead><tbody><tr><td><strong>Rollout (staged)</strong></td><td>A plan that widens a release&#39;s audience in stages — percentages or explicit tenant sets — each stage advancing only on plan.</td></tr><tr><td><strong>Cohort</strong></td><td>The deterministic set of tenants a rollout stage covers — the same plan on the same release always yields the same cohort.</td></tr><tr><td><strong>Distribution channel</strong></td><td>An external delivery rail (TestFlight, App Store, Google Play tracks, direct) a release dispatches through, with credentials bound per level.</td></tr><tr><td><strong>Signed URL</strong></td><td>The short-lived (minutes) download link the portal mints per tester per build — never a storage location, and it dies with the grant that minted it.</td></tr><tr><td><strong>Telemetry token</strong></td><td>The short-lived token a build carries when the team enabled telemetry — it lets the installed app report feedback and metrics without secrets.</td></tr></tbody></table><p>Deep dives: <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout how-to</a> · <a href="/shipperdog/snapshot/how-to/console/distribution-channels">distribution channels</a> · <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback and analytics</a></p><h2 id="reading-an-error" tabindex="-1">Reading an error <a class="header-anchor" href="#reading-an-error" aria-label="Permalink to &quot;Reading an error&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In one line</th></tr></thead><tbody><tr><td><strong>Fail-closed</strong></td><td>The design rule that missing data blocks rather than passes — a gate with no result is a blocking gate, not a waived one.</td></tr><tr><td><strong>Trace id</strong></td><td>The short identifier an error toast shows when present; quoting it lets an administrator join your failure to the exact server-side events.</td></tr></tbody></table><p>Deep dives: <a href="/shipperdog/snapshot/reference/error-codes">error codes</a> · <a href="/shipperdog/snapshot/reference/troubleshooting">troubleshooting</a></p><p><strong>Next:</strong> <a href="/shipperdog/snapshot/reference/error-codes">error codes</a> — the codes you can actually see, and what to do about them.</p>',18)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
